import {esc,attr,icon,dateLabel,formatDateRange,money,today,href,emptyState,initials,formatBytes} from './shared.js';
import {financeTotals,moneyFromMinor} from './domain.js';

const names={overview:'Поездка',packing:'Сборы',plan:'План по дням',documents:'Документы',tasks:'Задачи',discussions:'Обсуждения',budget:'Бюджет',templates:'Мои шаблоны',calendar:'Календарь подготовки',participants:'Участники',contacts:'Контакты и адреса',history:'История поездки',map:'Места на карте',accounts:'Счета',transactions:'История операций',settlements:'Распределение трат',profile:'Профиль',settings:'Настройки',storage:'Данные на устройстве',states:'Состояния приложения',invitation:'Приглашение',archive:'Архив поездок'};
const stateNames={missing:'Ещё нет',home:'Дома',packed:'Упаковано'};
const photoAliases={'kyoto':'kyoto-sunset','japan':'kyoto-sunset','candidate-36664010.jpg':'kyoto-sunset','kyoto-yasaka.jpg':'kyoto-sunset','kyoto-sunset':'kyoto-sunset','kyoto-sunset.jpg':'kyoto-sunset','amalfi':'amalfi','italy':'amalfi','positano-coast.jpg':'amalfi','barcelona':'barcelona','barcelona-guell.jpg':'barcelona','breakfast':'breakfast','japanese-breakfast.jpg':'breakfast','temple':'temple','kiyomizu-dera.jpg':'temple','alley':'kyoto-lanterns','kyoto-alley':'kyoto-lanterns','kyoto-alley.jpg':'kyoto-lanterns','kyoto-lanterns':'kyoto-lanterns','kyoto-lanterns.jpg':'kyoto-lanterns'};
const photoPath=value=>{ if(!value)return '';const key=String(value).split('/').pop();return photoAliases[key]?`assets/photos/${photoAliases[key]}.jpg`: /^assets\/photos\/[a-z-]+\.jpg$/.test(value)?value:''; };
const photo=(value,alt,cls='')=>photoPath(value)?`<img class="${cls}" src="${attr(photoPath(value))}" alt="${attr(alt)}" loading="lazy" decoding="async" width="900" height="600">`:`<div class="photo-fallback ${cls}" role="img" aria-label="Обложка не выбрана">${icon('location')}</div>`;
const btn=(label,action,opts={})=>`<button type="button" class="btn ${opts.primary?'primary ':''}${opts.ghost?'ghost ':''}${opts.danger?'danger ':''}${opts.full?'full ':''}${opts.class||''}" data-action="${action}"${opts.id!=null?` data-id="${attr(opts.id)}"`:''}${opts.kind?` data-kind="${attr(opts.kind)}"`:''}${opts.feature?` data-feature="${attr(opts.feature)}"`:''}${opts.disabled?' disabled':''}>${opts.icon?icon(opts.icon):''}<span>${esc(label)}</span></button>`;
const ibtn=(label,action,opts={})=>`<button type="button" class="icon-btn ${opts.primary?'primary':''} ${opts.class||''}" data-action="${action}"${opts.id!=null?` data-id="${attr(opts.id)}"`:''}${opts.feature?` data-feature="${attr(opts.feature)}"`:''} aria-label="${attr(label)}" title="${attr(label)}">${icon(opts.icon||'plus')}</button>`;
const badge=(text,tone='')=>`<span class="badge ${tone}">${esc(text)}</span>`;
const avatar=value=>`<span class="avatar" aria-hidden="true">${esc(initials(value))}</span>`;
const sectionTitle=(title,link,label)=>`<div class="section-title"><h2>${esc(title)}</h2>${link?`<a class="text-link" href="${attr(link)}">${esc(label||'Все')}${icon('chevron')}</a>`:''}</div>`;
const notice=(title,text,tone='info')=>`<aside class="notice ${tone}"><span class="notice-icon">${icon(tone==='error'?'warning':tone==='success'?'check':tone==='offline'?'wifi':'info')}</span><div><strong>${esc(title)}</strong><p>${esc(text)}</p></div></aside>`;
const linkRow=(title,meta,to,ic='chevron')=>`<a class="link-row" href="${attr(to)}"><span class="round-icon">${icon(ic)}</span><span class="row-copy"><strong>${esc(title)}</strong>${meta?`<small>${esc(meta)}</small>`:''}</span>${icon('chevron','row-arrow')}</a>`;
const dateOffset=(day,offset)=>{const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+offset);return d.toISOString().slice(0,10);};
const dayDiff=(a,b)=>Math.round((Date.parse(a+'T00:00:00Z')-Date.parse(b+'T00:00:00Z'))/86400000);
const memberName=m=>typeof m==='string'?m:m?.name||m?.displayName||'Участник';
const qget=(r,key,fallback='')=>r.query?.get(key)??fallback;
const qlink=(t,page,r,changes={})=>{const q=new URLSearchParams(r.query||'');for(const [k,v] of Object.entries(changes)){if(v===null||v==='')q.delete(k);else q.set(k,v);}return href(t?.id,page,null,q);};
const notFound=(kind='Запись')=>emptyState(`${kind} не найдена`,'Возможно, запись была удалена в другой вкладке. Вернитесь к поездке и проверьте её содержимое.',`<a class="btn primary" href="#/trips">К поездкам</a>`,'search');
const searchBox=(page,value='',placeholder='Поиск')=>`<form class="search-form" role="search" data-search-form="${page}"><label class="search-box">${icon('search')}<span class="sr-only">${esc(placeholder)}</span><input type="search" name="q" data-search="${page}" value="${attr(value)}" placeholder="${attr(placeholder)}" autocomplete="off"><button type="submit" class="icon-btn" aria-label="Найти">${icon('chevron')}</button></label></form>`;
const emptySearch=()=>emptyState('Ничего не найдено','Попробуйте другое название или сбросьте выбранные фильтры.',btn('Сбросить фильтры','clear-filters',{primary:true}),'search');
const compactTripName=t=>String(t.title||'Поездка').split(/\s+[·—–]\s+/)[0];
function header(ctx,title,opts={}){const t=ctx.trip;const back=opts.back|| (t?href(t.id,'overview'):'#/trips');return `<div class="header-inner"><a class="icon-btn back-button" href="${attr(back)}" aria-label="${t?'К обзору поездки':'К поездкам'}">${icon('arrow')}</a><div class="header-title"><h1>${esc(title)}</h1>${opts.subtitle!==false?`<p title="${attr(t?.title||title)}"${t?` aria-label="${attr(t.title+' · '+formatDateRange(t.start,t.end))}"`: ''}>${esc(opts.subtitle??(t?`${compactTripName(t)} · ${formatDateRange(t.start,t.end)}`:'TravelOrganizer'))}</p>`:''}</div>${opts.action?ibtn(opts.actionLabel||'Добавить',opts.action,{icon:opts.actionIcon||'plus',primary:opts.actionIcon!=='more',id:opts.id}):`<a class="icon-btn" href="#/settings" aria-label="Настройки">${icon('more')}</a>`}</div>`;}
function nav(ctx){const t=ctx.trip,r=ctx.route;const globals=['trips','archive','profile','settings','storage','templates','template','states'];const global=!t||globals.includes(r.page);const active=r.page;let entries=global?[['trips','Поездки','trips'],['archive','Архив','archive'],['create','Создать','plus'],['profile','Профиль','user']]:[['overview','Поездка','home'],['packing','Сборы','packing'],['plan','План','plan'],['documents','Документы','docs'],['discussions','Обсуждения','chat']];const selected=global?active:({item:'packing',templates:'packing',tasks:'packing',task:'packing',calendar:'packing',event:'plan',map:'plan',document:'documents'}[active]||active);return `<div class="nav-inner ${global?'global-nav':''}">${entries.map(([page,label,ic])=>page==='create'?`<button class="nav-item create-nav" data-action="new-trip" type="button">${icon(ic)}<span>${label}</span></button>`:`<a href="${attr(global?href(null,page):href(t.id,page))}" class="nav-item ${selected===page?'active':''}"${selected===page?' aria-current="page"':''}>${icon(ic)}<span>${label}</span></a>`).join('')}</div>`;}

function tripsView(ctx){const {data,route:r}=ctx;const archive=r.page==='archive';const q=qget(r,'q').toLocaleLowerCase('ru');const past=t=>Boolean(t.archived||(t.end&&t.end<today()));const all=(data.trips||[]).filter(t=>past(t)===archive);const filtered=all.filter(t=>!q||`${t.title} ${t.destinations||''}`.toLocaleLowerCase('ru').includes(q)).sort((a,b)=>(a.start||'9999').localeCompare(b.start||'9999'));const brand=`<div class="brand-header"><a class="brand" href="#/trips">TravelOrganizer</a><div class="brand-actions">${ibtn('Новая поездка','new-trip',{icon:'plus'})}<a href="#/profile" class="profile-link" aria-label="Профиль">${avatar(ctx.mode==='demo'?'Анна':data.profile?.name||'Вы')}</a></div></div>`;const cards=filtered.map(t=>{const days=t.start?dayDiff(t.start,today()):null;const nights=t.start&&t.end?dayDiff(t.end,t.start)+1:null;const caption=archive?'Завершена':days>0?`Через ${days} дн.`:days===0?'Начинается сегодня':t.start?'Уже началась':'Без дат';return `<article class="trip-card"><a href="${href(t.id)}" class="trip-card-link" aria-label="Открыть поездку: ${attr(t.title)}"><div class="trip-cover">${photo(t.cover,t.title)}<span class="cover-badge">${esc(caption)}</span></div><div class="trip-card-body"><h2>${esc(t.title)}</h2><p>${esc(formatDateRange(t.start,t.end))}</p><div class="trip-meta-row"><span>${icon('people')}${(t.members||[]).length||1} участн.</span>${nights?`<span>${icon('clock')}${nights} дн.</span>`:''}<span class="card-arrow">${icon('chevron')}</span></div></div></a></article>`;}).join('');const archived=(data.trips||[]).filter(past);const pastSection=!archive&&archived.length?`${sectionTitle('Прошлые поездки','#/archive','Архив')}<div class="compact-list">${archived.slice(0,2).map(t=>`<a class="archive-row" href="${href(t.id)}">${photo(t.cover,t.title)}<span class="row-copy"><strong>${esc(t.title)}</strong><small>${esc(formatDateRange(t.start,t.end))}</small></span>${icon('chevron')}</a>`).join('')}</div>`:'';return {header:archive?header(ctx,'Архив поездок',{subtitle:'Воспоминания и сохранённые записи'}):brand,content:`<div class="page-inner trips-page">${all.length>3||q?searchBox(archive?'archive':'trips',q,'Найти поездку'):''}${sectionTitle(archive?'Прошлые поездки':'Предстоящие поездки',archive?'#/trips':null,archive?'Предстоящие':null)}${filtered.length?`<div class="trip-grid">${cards}</div>`:q?emptySearch():emptyState(archive?'Здесь будут прошлые поездки':'Куда отправимся? ',archive?'Завершённые и архивные поездки останутся со всеми вашими записями.':'Создайте первую поездку: вещи, планы и важные документы будут рядом.',btn('Создать поездку','new-trip',{primary:true,icon:'plus'}),'trips')}${pastSection}${!data.trips?.length&&ctx.mode!=='demo'?`<div class="demo-entry">${btn('Посмотреть демопример','choose-demo',{ghost:true})}<p>Отдельные синтетические данные. Ваши записи сохранятся.</p></div>`:''}</div>`};}

function overview(ctx){const t=ctx.trip;const packed=t.items.filter(i=>i.status==='packed').length;const days=t.start?dayDiff(t.start,today()):null;const left=t.tasks.filter(i=>!i.completed&&!i.done).length;const totals=financeTotals(t);const actions=[['plan','План',t.start&&t.end?`${dayDiff(t.end,t.start)+1} дней`:`${t.events.length} событий`,'plan'],['packing','Вещи',`${packed}/${t.items.length} упаковано`,'packing'],['documents','Документы',`${t.docs.length} записей`,'docs'],['budget','Бюджет',totals.hasBudget?money(totals.budgetDecimal,t.currency):'Настроить бюджет','money'],['tasks','Задачи',`${left} осталось`,'tasks'],['discussions','Обсуждения',ctx.mode==='demo'?'Демо переписки':'Не подключены','chat']];return {header:'',content:`<div class="overview-page"><section class="trip-hero">${photo(t.cover,t.title,'hero-image')}<div class="hero-shade"></div><div class="hero-tools"><a class="icon-btn surface" href="#/trips" aria-label="Мои поездки">${icon('arrow')}</a>${ibtn('Редактировать поездку','edit-trip',{id:t.id,icon:'more',class:'surface'})}</div><div class="hero-copy"><h1>${esc(t.title)}</h1><p>${esc(formatDateRange(t.start,t.end))}</p></div><div class="participants-line hero-participants"><a class="people-link" href="${href(t.id,'participants')}" aria-label="Участники поездки"><span class="avatar-stack">${(t.members||['Вы']).slice(0,3).map(m=>avatar(memberName(m))).join('')}</span><span>${(t.members||[]).length||1} участн.</span></a>${btn('Пригласить','show-integration',{feature:'invitation',icon:'people'})}</div></section><div class="page-inner overview-inner">${days!=null&&days>0?`<div class="countdown-card"><strong>${days}</strong><div><b>дней до путешествия</b><small>Время отправления не задано</small></div>${icon('plane')}</div>`:days===0?notice('Счастливого путешествия!','Поездка начинается сегодня. Все планы и документы — под рукой.','success'):days!=null&&days<0?notice(t.end&&t.end<today()?'Поездка завершена':'Путешествие уже началось','Записи, планы и расходы останутся в вашей поездке.','success'):notice('Путешествие начинается с идеи','Даты можно выбрать позже. А список вещей и план — собрать уже сейчас.')}<p class="trip-motto">${esc(t.description||'Немного планов — и больше свободы в пути.')}</p><div class="action-grid">${actions.map(([page,label,sub,ic])=>`<a class="action-card" href="${href(t.id,page)}"><span class="round-icon">${icon(ic)}</span><span><strong>${label}</strong><small>${esc(sub)}</small></span></a>`).join('')}</div><div class="card detail-links">${linkRow('О поездке',t.destinations||t.description||'Даты, направления и описание',href(t.id,'overview')+'?details=1','location')}${qget(ctx.route,'details')?`<div class="trip-details-expanded"><dl class="detail-list"><div><dt>Направления</dt><dd>${esc(t.destinations||'Не указаны')}</dd></div><div><dt>Основная валюта</dt><dd>${esc(t.currency)}</dd></div><div><dt>Описание</dt><dd>${esc(t.description||'Пока без описания')}</dd></div></dl>${btn('Изменить поездку','edit-trip',{id:t.id,ghost:true,icon:'edit'})}</div>`:''}${linkRow('Контакты и адреса',`${(t.contacts||[]).length} сохранено`,href(t.id,'contacts'),'phone')}${linkRow('История поездки','Локальные изменения',href(t.id,'history'),'clock')}</div>${t.pins?.length?`${sectionTitle('Закреплено')}<div class="card compact-list">${t.pins.map(id=>t.docs.find(d=>d.id===id)).filter(Boolean).map(d=>linkRow(d.title,d.filePresent?'Копия на устройстве':'Запись без файла',href(t.id,'document',d.id),'pin')).join('')}</div>`:''}<div class="secondary-actions">${btn(t.archived?'Вернуть из архива':'В архив','archive-trip',{id:t.id,ghost:true,icon:'archive'})}${btn('Удалить поездку','delete-trip',{id:t.id,danger:true,ghost:true})}</div></div></div>`};}

function packing(ctx){const t=ctx.trip,r=ctx.route;const chosen=qget(r,'state','all');const q=qget(r,'q').toLocaleLowerCase('ru');const assignee=qget(r,'assignee');const packed=t.items.filter(i=>i.status==='packed').length;const pct=t.items.length?Math.round(packed/t.items.length*100):0;const filtered=t.items.filter(i=>(chosen==='all'||i.status===chosen)&&(!q||`${i.title} ${i.category}`.toLocaleLowerCase('ru').includes(q))&&(!assignee||i.assignee===assignee));const groups=new Map();for(const i of filtered){const category=i.category||'Без категории';if(!groups.has(category))groups.set(category,[]);groups.get(category).push(i);}const preview=chosen==='all'&&!q&&!assignee;const categoryRank=name=>{const key=name.trim().toLocaleLowerCase('ru');return key==='необходимое'?0:key==='одежда'?1:2;};const things=n=>`${n} ${n%10===1&&n%100!==11?'вещь':n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?'вещи':'вещей'}`;const itemRows=items=>items.map(i=>`<li class="item-row" data-long-item="${attr(i.id)}"><button type="button" class="state-marker ${i.status}" data-action="item-state" data-id="${attr(i.id)}" aria-label="Изменить состояние вещи ${attr(i.title)}: ${stateNames[i.status]||'Ещё нет'}">${i.status==='packed'?icon('check'):i.status==='home'?'<span>Д</span>':'<span>−</span>'}</button><a href="${href(t.id,'item',i.id)}" class="item-title"><strong>${esc(i.title)}${Number(i.quantity)>1?` <span class="quantity">×${esc(i.quantity)}</span>`:''}</strong>${i.assignee?`<small>${esc(i.assignee)}</small>`:''}</a><button type="button" class="icon-btn row-menu" data-action="item-state" data-id="${attr(i.id)}" aria-label="Состояние вещи ${attr(i.title)}">${icon('more')}</button></li>`).join('');const categoryCount=(name,status)=>t.items.filter(i=>(i.category||'Без категории')===name&&(!status||i.status===status)).length;const categoryIcon=n=>/одежд|обув/i.test(n)?'shirt':/докум/i.test(n)?'docs':'packing';return {header:header(ctx,'Сборы',{action:'new-item',actionLabel:'Добавить вещь'}),content:`<div class="page-inner packing-page"><div class="packing-progress"><div><strong>${packed} из ${t.items.length} вещей упаковано</strong><span>${pct}%</span></div><progress value="${packed}" max="${t.items.length||1}" aria-label="Упаковано вещей">${pct}%</progress></div><div class="state-tabs" aria-label="Состояние вещей">${Object.entries(stateNames).map(([state,label])=>`<a href="${qlink(t,'packing',r,{state})}" class="state-tab ${chosen===state?'active':''}"${chosen===state?' aria-current="true"':''}><span>${label}</span><strong>${t.items.filter(i=>i.status===state).length}</strong></a>`).join('')}</div><div class="packing-tools"><a class="packing-all ${chosen==='all'?'is-current':''}" href="${qlink(t,'packing',r,{state:'all'})}"${chosen==='all'?' aria-current="true"':''}>Все вещи</a><a class="btn ghost" href="#/templates">${icon('tasks')}Шаблоны</a><details class="search-disclosure compact-packing-filter"${q||assignee?' open':''}><summary>${icon('search')}Поиск и фильтры${q||assignee?badge('Активны','accent'):''}</summary><div class="filter-panel"><a class="btn ghost" href="${href(t.id,'packing',null,{state:'all'})}">Все вещи · сбросить фильтры</a>${searchBox('packing',q,'Название или категория')}<label class="filter-select">Ответственный<select data-filter="assignee" name="assignee"><option value="">Все</option>${[...new Set(t.items.map(i=>i.assignee).filter(Boolean))].map(n=>`<option value="${attr(n)}"${assignee===n?' selected':''}>${esc(n)}</option>`).join('')}</select></label></div></details></div>${filtered.length?`<div class="packing-groups">${[...groups].sort((a,b)=>categoryRank(a[0])-categoryRank(b[0])||b[1].length-a[1].length).map(([category,items])=>`<section class="packing-group card"><h2>${icon(categoryIcon(category))}<span>${esc(category)}</span><small aria-label="Упаковано в категории: ${categoryCount(category,'packed')} из ${categoryCount(category)}">${categoryCount(category,'packed')}/${categoryCount(category)}</small></h2>${preview&&items.length>5?`<ul class="item-list">${itemRows(items.slice(0,5))}</ul><details class="packing-more"><summary>Ещё ${things(items.length-5)}<span class="sr-only"> в категории «${esc(category)}»</span></summary><ul class="item-list">${itemRows(items.slice(5))}</ul></details>`:`<ul class="item-list">${itemRows(items)}</ul>`}</section>`).join('')}</div>`:q||assignee?emptySearch():emptyState(chosen==='all'?'Список ещё пуст':chosen==='packed'?'Багаж пока не собран':chosen==='home'?'Дома пока ничего не отмечено':'Всё необходимое уже есть',chosen==='missing'&&t.items.length?'Выберите «Дома» или «Упаковано», чтобы продолжить сборы.':'Добавьте первую вещь или примените личный шаблон.',btn('Добавить вещь','new-item',{primary:true,icon:'plus'}),'packing')}<p class="helper-text">Нажмите название для подробностей. Удерживайте строку или используйте кнопку состояния, чтобы переместить вещь.</p></div>`};}

function plan(ctx){const t=ctx.trip,r=ctx.route;const undated=qget(r,'undated')==='1';const selected=qget(r,'day',t.day||t.start||today());let start=t.start||selected;if(!/^\d{4}-\d{2}-\d{2}$/.test(start))start=today();const dates=[];let span=t.start&&t.end?Math.min(Math.max(1,dayDiff(t.end,t.start)+1),60):7;for(let i=0;i<span;i++)dates.push(dateOffset(start,i));if(!dates.includes(selected))dates.push(selected);dates.sort();const events=t.events.filter(e=>undated?!e.date:e.date===selected).sort((a,b)=>(a.time||'99:99').localeCompare(b.time||'99:99'));const without=t.events.filter(e=>!e.date).length;const dayNum=t.start?dayDiff(selected,t.start)+1:null;return {header:header(ctx,'План по дням',{action:'new-event',actionLabel:'Добавить событие'}),content:`<div class="page-inner plan-page"><div class="date-strip" aria-label="Дни поездки">${dates.map(d=>`<a href="${href(t.id,'plan',null,{day:d})}" class="date-tile ${!undated&&d===selected?'active':''}"${!undated&&d===selected?' aria-current="date"':''}><span>${esc(dateLabel(d,{weekday:'short',day:undefined,month:undefined}))}</span><strong>${new Date(d+'T12:00:00').getDate()}</strong><span>${esc(dateLabel(d,{month:'short',day:undefined}))}</span></a>`).join('')}</div><div class="day-heading"><div><h2>${undated?'День не назначен':dayNum>0?`День ${dayNum}${t.destinations?` · ${esc(String(t.destinations).split(',').pop().trim())}`:''}`:esc(dateLabel(selected,{weekday:'long',year:'numeric'}))}</h2><p>${undated?'Идеи, которые можно добавить в маршрут позже':esc(dateLabel(selected,{weekday:'long',year:'numeric'}))}</p></div><details class="plan-tools"${undated?' open':''}><summary>${icon('plan')}<span>Дни и места</span></summary><div class="plan-tools-panel"><a class="text-link" href="${href(t.id,'plan',null,{day:today()})}">Сегодня</a><label class="date-jump"><span>Выбрать день</span><input type="date" value="${attr(selected)}" data-plan-date data-filter="day" aria-label="Выбрать день"></label><a class="btn ghost ${undated?'selected':''}" href="${href(t.id,'plan',null,{undated:'1'})}">Без дня${without?` · ${without}`:''}</a><a class="btn ghost" href="${href(t.id,'map')}">${icon('location')}Места на карте</a></div></details></div>${events.length?`<ol class="timeline">${events.map((e,i)=>`<li class="event-row"><div class="event-time"><time>${esc(e.time||'—')}</time><span class="timeline-dot tone-${i%3}"></span></div><a class="event-content" href="${href(t.id,'event',e.id)}">${e.photo?photo(e.photo,e.title,'event-photo'):''}<span class="event-copy"><strong>${esc(e.title)}</strong>${e.notes||e.note?`<span>${esc(e.notes||e.note)}</span>`:''}${e.address?`<small>${icon('location')}${esc(e.address)}</small>`:''}${e.documentId?`<small class="related-label">${icon('docs')}Связан документ</small>`:''}</span>${icon('more','event-more')}</a></li>`).join('')}</ol>`:emptyState(undated?'Здесь будут идеи без даты':'День свободен',undated?'Сохраняйте идеи, не назначая им день.':'Добавьте прогулку, встречу или важный переезд. Дата может остаться открытой.',btn('Добавить событие','new-event',{primary:true,icon:'plus'}),'plan')}</div>`};}

function documents(ctx){
 const t=ctx.trip,r=ctx.route;
 const q=qget(r,'q').toLocaleLowerCase('ru'),cat=qget(r,'category','all');
 const categories=[['all','Все'],['booking','Брони'],['ticket','Билеты'],['personal','Личное']];
 const category=d=>{const c=String(d.category||'').toLowerCase();return /брон|отел|booking/.test(c)?'booking':/билет|ticket|перел/.test(c)?'ticket':/лич|personal|паспорт/.test(c)?'personal':'other';};
 const metadata=d=>d.filePresent?`${d.fileType==='application/pdf'?'PDF':'Изображение'} · ${formatBytes(d.fileSize)}`:d.note||d.notes||d.owner||'Запись без файла';
 const filtered=t.docs.filter(d=>(cat==='all'||category(d)===cat)&&(!q||`${d.title} ${d.note||d.notes||''} ${d.owner||''}`.toLowerCase().includes(q)));
 return {header:header(ctx,'Документы',{action:'new-document',actionLabel:'Добавить документ'}),content:`<div class="page-inner documents-page"><div class="document-toolbar"><div class="chip-strip" aria-label="Категории документов">${categories.map(([key,label])=>`<a class="chip ${cat===key?'active':''}" href="${qlink(t,'documents',r,{category:key})}">${label}</a>`).join('')}</div><div class="document-tools"><span class="document-count sr-only">${filtered.length} из ${t.docs.length}</span><details class="compact-search"${q?' open':''}><summary aria-label="Найти документ">${icon('search')}<span class="sr-only">Найти документ</span></summary>${searchBox('documents',q,'Название или реквизиты')}</details></div></div>${filtered.length?`<ul class="document-list card">${filtered.map(d=>`<li class="document-row"><span class="document-icon">${icon(category(d)==='booking'?'building':category(d)==='ticket'?'plane':category(d)==='personal'?'lock':'docs')}</span><a href="${href(t.id,'document',d.id)}" class="row-copy document-copy"><strong>${esc(d.title)}</strong><small class="document-meta" title="${attr(metadata(d))}">${esc(metadata(d))}</small><span class="document-statuses document-facts"><span class="document-audience">${icon('lock')}${esc(d.audience||'Только мне')}</span>${badge(d.filePresent?'На устройстве':'Без файла',d.filePresent?'success':'muted')}${t.pins?.includes(d.id)?`<span class="pin-label" aria-label="Закреплено">${icon('pin')}</span>`:''}</span></a><a class="icon-btn" href="${href(t.id,'document',d.id)}" aria-label="Подробности документа ${attr(d.title)}">${icon('more')}</a></li>`).join('')}</ul>`:q||cat!=='all'?emptySearch():emptyState('Всё важное — под рукой','Добавьте PDF, изображение или запись с реквизитами. Локальная копия останется на этом устройстве.',btn('Добавить документ','new-document',{primary:true,icon:'plus'}),'docs')}<div class="list-footer document-add">${btn('Добавить документ','new-document',{primary:true,icon:'plus'})}</div><p class="helper-text">Документы хранятся только на этом устройстве. Обмен с участниками пока недоступен.</p></div>`};
}

function taskRow(t,x){const done=Boolean(x.completed||x.done);return `<li class="task-row ${done?'completed':''}"><span class="task-calendar">${icon('plan')}</span><a class="row-copy" href="${href(t.id,'task',x.id)}"><strong>${esc(x.title)}</strong><small class="${x.due&&x.due<today()&&!done?'overdue':''}">${done?'Завершено':x.due?dateLabel(x.due,{year:'numeric'}):'Без срока'}${x.assignee?` · ${esc(x.assignee)}`:''}${x.priority==='high'?' · Высокий приоритет':''}</small></a><button type="button" class="task-checkbox" role="checkbox" aria-checked="${done}" aria-label="${done?'Вернуть в работу':'Завершить'}: ${attr(x.title)}" data-action="toggle-task" data-id="${attr(x.id)}"><span>${done?icon('check'):''}</span></button></li>`;}
function tasks(ctx){const t=ctx.trip,r=ctx.route;const filter=qget(r,'filter','all');const q=qget(r,'q').toLocaleLowerCase('ru');const data=t.tasks.filter(x=>(!q||x.title.toLocaleLowerCase('ru').includes(q))&&(filter==='all'||filter==='done'&&(x.completed||x.done)||filter==='before'&&(x.phase||'before')==='before'&&!x.completed&&!x.done||filter==='during'&&x.phase==='during'&&!x.completed&&!x.done||filter==='after'&&x.phase==='after'&&!x.completed&&!x.done));const done=data.filter(x=>x.completed||x.done),todo=data.filter(x=>!x.completed&&!x.done);const groups=[['Ближайшие',todo.filter(x=>x.due&&dayDiff(x.due,today())<=7).sort((a,b)=>a.due.localeCompare(b.due))],['Позже',todo.filter(x=>x.due&&dayDiff(x.due,today())>7).sort((a,b)=>a.due.localeCompare(b.due))],['Без срока',todo.filter(x=>!x.due)],['Завершено',done]];return {header:header(ctx,'Задачи',{action:'new-task',actionLabel:'Добавить задачу'}),content:`<div class="page-inner tasks-page"><div class="chip-strip" aria-label="Фильтр задач">${[['all','Все'],['before','До поездки'],['during','В поездке'],['after','После'],['done','Готово']].map(([key,label])=>`<a class="chip ${filter===key?'active':''}" href="${qlink(t,'tasks',r,{filter:key})}">${label}</a>`).join('')}</div><div class="task-tools"><a href="${href(t.id,'calendar')}" class="text-link">${icon('plan')}Календарь подготовки</a><details class="compact-search"${q?' open':''}><summary aria-label="Поиск задач">${icon('search')}<span>Поиск</span></summary>${searchBox('tasks',q,'Найти задачу')}</details></div>${data.length?groups.filter(([,items])=>items.length).map(([label,items])=>`<section class="task-group"><h2>${label}</h2><ul>${items.map(x=>taskRow(t,x)).join('')}</ul></section>`).join(''):q||filter!=='all'?emptySearch():emptyState('Планы начинаются с маленьких дел','Запишите, что нужно сделать до, во время или после поездки. Срок можно добавить позже.',btn('Добавить задачу','new-task',{primary:true,icon:'plus'}),'tasks')}<div class="list-footer">${btn('Добавить задачу','new-task',{primary:true,icon:'plus'})}</div></div>`};}

function discussions(ctx){const t=ctx.trip;if(ctx.mode!=='demo')return {header:header(ctx,'Обсуждения'),content:`<div class="page-inner discussion-page">${emptyState('Путешествовать вместе — приятнее','Совместные обсуждения пока не подключены. Ваши локальные планы и документы доступны, но сообщения участникам не отправляются.',btn('О совместной работе','show-integration',{primary:true,feature:'sync',icon:'chat'}),'chat')}<div class="card integration-preview"><span class="round-icon">${icon('people')}</span><h2>Одна поездка — общий план</h2><p>Сообщения, контекстные карточки и голосования появятся после подключения аккаунтов и серверной синхронизации.</p>${btn('Посмотреть демопример','choose-demo',{ghost:true})}</div></div>`};const filter=qget(ctx.route,'filter','all');const context=qget(ctx.route,'context');const contextId=qget(ctx.route,'id');const contextLabel={item:'вещи',event:'события',task:'задачи',document:'документа'}[context];const messages=(t.messages||[]).filter(m=>(!context||(m.contextType===context&&m.contextId===contextId)||m[context+'Id']===contextId)&&(filter==='all'||filter==='general'&&!m.card||filter==='questions'&&String(m.text).includes('?')));const poll=!context&&['all','decisions'].includes(filter)?t.poll||t.polls?.[0]:null;const total=poll?.options.reduce((s,o)=>s+(Number(o.votes)||0),0)||0;return {header:header(ctx,'Обсуждения',{subtitle:`${compactTripName(t)} · демопереписка`}),content:`<div class="page-inner discussion-page"><div class="chip-strip">${[['all','Все'],['decisions','Решения'],['questions','Вопросы'],['general','Общее']].map(([key,label])=>`<a class="chip ${filter===key?'active':''}" href="${qlink(t,'discussions',ctx.route,{filter:key})}">${label}</a>`).join('')}</div>${contextLabel?notice('Обсуждение '+contextLabel,'Отдельный контекст объекта. Демосообщения сохраняются только в этом обсуждении.'):''}<div class="conversation-stream"><div class="messages">${!messages.length&&!poll?'<p class="empty-inline">В этом обсуждении пока нет сообщений.</p>':''}${messages.map(m=>`<article class="message ${m.author==='Вы'?'own':''}">${avatar(m.author)}<div class="message-body"><div class="message-meta"><strong>${esc(m.author||'Участник')}</strong><time>${esc(m.time?dateLabel(m.time,{hour:'2-digit',minute:'2-digit'}):'Демо')}</time></div><p>${esc(m.text)}</p>${m.card?`<a class="chat-place-card" href="${m.eventId?href(t.id,'event',m.eventId):href(t.id,'plan',null,{undated:'1'})}">${photo(m.card.photo||'kyoto-alley',m.card.title)}<span><strong>${esc(m.card.title)}</strong><small>Идея для поездки · день можно выбрать позже</small></span>${icon('chevron')}</a>`:''}</div></article>`).join('')}</div>${poll?`<section class="poll card"><div class="poll-title">${icon('money')}<div><h2>${esc(poll.title)}</h2><p>Демоголосование · ${total} ответа</p></div></div>${poll.options.map(o=>{const pct=total?Math.round((Number(o.votes)||0)/total*100):0;return `<button type="button" class="poll-option ${poll.myVote===o.id?'selected':''}" data-action="demo-vote" data-id="${attr(o.id)}" aria-pressed="${poll.myVote===o.id}"><span class="poll-check">${poll.myVote===o.id?icon('check'):''}</span><span class="poll-option-body"><span><strong>${esc(o.text)}</strong><small>${pct}% (${Number(o.votes)||0})</small></span><span class="poll-bar"><span style="width:${pct}%"></span></span></span></button>`;}).join('')}</section>`:''}</div><form class="chat-composer" id="demo-message-form" data-demo-message><label class="sr-only" for="demo-message">Сообщение в деморежиме</label><input id="demo-message" name="message" maxlength="2000" placeholder="Написать в деморежиме…" required autocomplete="off"><button type="submit" class="icon-btn send-button" aria-label="Добавить сообщение в деморежим">${icon('send')}</button></form></div>`};}

function budget(ctx){const t=ctx.trip,z=financeTotals(t);const percent=Number.isFinite(z.percent)?Math.max(0,Math.min(100,z.percent)):0;const sum=(v)=>money(v,t.currency);const operations=n=>`${n} ${n%10===1&&n%100!==11?'операция':n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?'операции':'операций'}`;const categoryRows=t.categories.map(c=>({c,value:z.byCategoryDecimal?.[c.id]??z.byCategory?.[c.id]??0})).filter(({value})=>!/^[-+]?0(?:\.0*)?$/.test(String(value)));return {header:header(ctx,'Бюджет',{action:'new-expense',actionLabel:'Добавить расход'}),content:`<div class="page-inner budget-page"><section class="budget-summary card"><div class="budget-summary-top"><div><p>Плановый бюджет</p><h2>${z.hasBudget?sum(z.budgetDecimal):'Не задан'}</h2></div>${btn('Изменить','edit-budget',{ghost:true})}</div>${z.hasBudget?`<progress class="${z.exceeded?'over-budget':''}" max="100" value="${percent}" aria-label="Использовано бюджета">${percent}%</progress>`:''}<div class="budget-numbers"><div><strong>${sum(z.spentDecimal)}</strong><span>Потрачено</span></div><div class="${z.exceeded?'danger-text':''}"><strong>${z.hasBudget?sum(z.remainingDecimal):'—'}</strong><span>${z.exceeded?'Превышение':'Осталось'}</span></div>${z.hasBudget?`<div><strong>${Math.round(z.percent||0)}%</strong><span>Использовано</span></div>`:''}</div></section>${z.complete===false?notice('Не все суммы можно объединить','В истории есть разные валюты или неподдерживаемая точность. Они сохранены отдельно; общий итог не является конвертацией.','error'):''}<div class="section-title budget-category-heading"><h2>Расходы</h2>${btn('Добавить расход','new-expense',{ghost:true,icon:'plus'})}</div><div class="expense-categories">${categoryRows.map(({c,value})=>`<div class="expense-category" data-money-category="${attr(c.id)}"><span class="round-icon">${icon(/еда|food/i.test(c.name)?'food':/жиль|отел|прож/i.test(c.name)?'building':/трансп|перел|flight/i.test(c.name)?'plane':/покуп|сувен/i.test(c.name)?'packing':'money')}</span><div class="row-copy"><strong>${esc(c.name)}</strong><small>${operations(t.transactions.filter(x=>x.type==='expense'&&x.categoryId===c.id).length)}</small></div><strong class="expense-value">${sum(value)}</strong></div>`).join('')||`<p class="empty-inline">Пока без расходов. Все категории доступны в форме добавления.</p>`}</div><div class="budget-links"><a class="text-link" href="${href(t.id,'accounts')}">${icon('wallet')}Счета и переводы${icon('chevron')}</a>${btn('Категория','new-category',{ghost:true,icon:'plus'})}</div><div class="section-title"><h2>Деньги на счетах</h2><a class="text-link" href="${href(t.id,'accounts')}">Все ${icon('chevron')}</a></div><div class="account-grid">${t.accounts.map(a=>`<button class="account-card card" type="button" data-action="edit-account" data-money-account="${attr(a.id)}" data-id="${attr(a.id)}"><span>${icon(a.kind==='storage'?'building':'wallet')}${esc(a.name)}</span><strong>${money(a.balanceMinor!=null?moneyFromMinor(a.balanceMinor,t.currency):a.balance,t.currency)}</strong></button>`).join('')}</div><div class="button-row financial-actions">${btn('Перевести','new-transfer',{icon:'transfer'})}<a class="btn" href="${href(t.id,'transactions')}">${icon('clock')}История</a></div><div class="card detail-links">${linkRow('Распределить расходы','Доли, взаиморасчёты и погашение',href(t.id,'settlements'),'people')}</div><p class="helper-text">Остатки на счетах показываются отдельно от бюджета. Перевод между счетами не увеличивает расходы.</p></div>`};}

const detailRows=rows=>`<dl class="detail-list">${rows.filter(([,value])=>value!==undefined).map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value||'Не указано')}</dd></div>`).join('')}</dl>`;
const safeUrl=value=>{try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)?u.href:'';}catch{return '';}};
function itemDetail(ctx){const t=ctx.trip,x=t.items.find(i=>i.id===ctx.route.id);if(!x)return {header:header(ctx,'Вещь'),content:notFound('Вещь')};const task=t.tasks.find(y=>y.id===x.taskId);return {header:header(ctx,'Подробности вещи',{back:href(t.id,'packing'),action:'edit-item',actionLabel:'Редактировать вещь',actionIcon:'edit',id:x.id}),content:`<div class="page-inner detail-page"><div class="detail-heading"><span class="detail-symbol">${icon('packing')}</span><h2>${esc(x.title)}</h2>${badge(stateNames[x.status]||'Ещё нет',x.status==='packed'?'success':'accent')}</div><section class="card detail-card">${detailRows([['Количество',String(x.quantity||1)],['Категория',x.category||'Без категории'],['Ответственный',x.assignee||'Не назначен']])}${btn('Изменить состояние','item-state',{id:x.id,icon:'transfer',full:true})}</section>${x.note||x.notes?`<section class="card detail-card"><h2>Заметка</h2><p class="preline">${esc(x.note||x.notes)}</p></section>`:''}${safeUrl(x.url||x.link)?`<a class="btn full" href="${attr(safeUrl(x.url||x.link))}" target="_blank" rel="noopener noreferrer">${icon('globe')}Товарная ссылка</a>`:''}${sectionTitle('Связи')}<div class="card detail-links">${task?linkRow(task.title,task.completed?'Задача выполнена':'Связанная задача',href(t.id,'task',task.id),'tasks'):`<p class="empty-inline">Связанных задач пока нет.</p>`}${linkRow('Обсуждение вещи',ctx.mode==='demo'?'Демонстрация':'Совместная работа не подключена',href(t.id,'discussions',null,{context:'item',id:x.id}),'chat')}</div>${x.createdAt||x.createdBy?`<p class="helper-text">${esc(x.createdBy||'Создано на этом устройстве')}${x.createdAt?` · ${esc(dateLabel(x.createdAt,{year:'numeric',hour:'2-digit',minute:'2-digit'}))}`:''}</p>`:''}<div class="button-row">${btn('Редактировать','edit-item',{primary:true,id:x.id,icon:'edit'})}${btn('Удалить','delete-item',{id:x.id,danger:true,ghost:true,icon:'trash'})}</div></div>`};}
function eventDetail(ctx){const t=ctx.trip,x=t.events.find(e=>e.id===ctx.route.id);if(!x)return {header:header(ctx,'Событие'),content:notFound('Событие')};const doc=t.docs.find(d=>d.id===x.documentId);return {header:header(ctx,'Событие',{back:href(t.id,'plan',null,x.date?{day:x.date}:{undated:'1'}),action:'edit-event',actionIcon:'edit',actionLabel:'Редактировать событие',id:x.id}),content:`<div class="page-inner detail-page">${x.photo?`<div class="detail-photo">${photo(x.photo,x.title)}</div>`:''}<div class="detail-heading"><h2>${esc(x.title)}</h2>${badge(x.date?dateLabel(x.date,{year:'numeric'}):'День не назначен',x.date?'':'accent')}</div><section class="card detail-card">${detailRows([['Время',x.time?`${x.time}${(x.timeZone||x.timezone||x.zone)?` · ${x.timeZone||x.timezone||x.zone}`:''}`:'Не задано'],['Адрес',x.address],['Категория',x.category||'Без категории'],['Контакт',x.contact]])}${x.address?`<button type="button" class="btn full" data-action="copy-address" data-address="${attr(x.address)}">${icon('copy')}Скопировать адрес</button>`:''}</section>${x.notes||x.note?`<section class="card detail-card"><h2>Заметки</h2><p class="preline">${esc(x.notes||x.note)}</p></section>`:''}<div class="card detail-links">${doc?linkRow(doc.title,doc.filePresent?'На устройстве':'Запись без файла',href(t.id,'document',doc.id),'docs'):''}${linkRow('Открыть карту','Список адресов · карта не подключена',href(t.id,'map'),'location')}${linkRow('Обсуждение события',ctx.mode==='demo'?'Демонстрация':'Сервер не подключён',href(t.id,'discussions',null,{context:'event',id:x.id}),'chat')}</div><div class="button-row">${btn(x.date?'Изменить':'Назначить день','edit-event',{primary:true,id:x.id,icon:'edit'})}${btn('Удалить','delete-event',{id:x.id,ghost:true,danger:true,icon:'trash'})}</div></div>`};}
function taskDetail(ctx){const t=ctx.trip,x=t.tasks.find(e=>e.id===ctx.route.id);if(!x)return {header:header(ctx,'Задача'),content:notFound('Задача')};const item=t.items.find(i=>i.taskId===x.id);const done=x.completed||x.done;return {header:header(ctx,'Задача',{back:href(t.id,'tasks'),action:'edit-task',actionIcon:'edit',actionLabel:'Редактировать задачу',id:x.id}),content:`<div class="page-inner detail-page"><div class="detail-heading"><span class="detail-symbol">${icon('tasks')}</span><h2>${esc(x.title)}</h2>${badge(done?'Выполнена':'В работе',done?'success':'accent')}</div><section class="card detail-card">${detailRows([['Срок',x.due?dateLabel(x.due,{year:'numeric'}):'Без срока'],['Время и зона',x.time?`${x.time} · ${x.timeZone||x.timezone||x.zone||Intl.DateTimeFormat().resolvedOptions().timeZone}`:'Не заданы'],['Ответственный',x.assignee||'Не назначен'],['Этап',{before:'До поездки',during:'Во время поездки',after:'После поездки'}[x.phase]||'До поездки'],['Напоминание',x.due&&x.reminder&&!['none','',false].includes(x.reminder)?`${x.reminder} · фоновая доставка не подключена`:'Не задано']])}${btn(done?'Вернуть в работу':'Завершить задачу','toggle-task',{primary:true,id:x.id,icon:done?'refresh':'check',full:true})}</section>${x.notes||x.note?`<section class="card detail-card"><h2>Описание</h2><p class="preline">${esc(x.notes||x.note)}</p></section>`:''}${item?`<div class="card detail-links">${linkRow(item.title,`Вещь · ${stateNames[item.status]}`,href(t.id,'item',item.id),'packing')}</div><p class="helper-text">Выполнение задачи не меняет состояние связанной вещи.</p>`:''}<div class="card detail-links">${linkRow('Календарь подготовки','Дела за месяцы до путешествия',href(t.id,'calendar'),'plan')}${linkRow('Уведомления','Разрешение и ограничения доставки','#/settings?section=notifications','bell')}</div><div class="button-row">${btn('Редактировать','edit-task',{primary:true,id:x.id,icon:'edit'})}${btn('Удалить','delete-task',{id:x.id,ghost:true,danger:true,icon:'trash'})}</div></div>`};}
function documentDetail(ctx){const t=ctx.trip,x=t.docs.find(d=>d.id===ctx.route.id);if(!x)return {header:header(ctx,'Документ'),content:notFound('Запись')};const event=t.events.find(e=>e.id===x.eventId);return {header:header(ctx,'Документ',{back:href(t.id,'documents'),action:'edit-document',actionLabel:'Изменить запись',actionIcon:'edit',id:x.id}),content:`<div class="page-inner detail-page">${x.filePresent?'<div id="file-preview" class="document-file-preview"></div>':''}<div class="document-preview-placeholder"><span>${icon(x.filePresent?'docs':'upload')}</span><strong>${esc(x.fileName||x.title)}</strong><small>${x.filePresent?`${x.fileType==='application/pdf'?'PDF':esc(x.fileType||'Файл')} · ${formatBytes(x.fileSize)}`:'Запись без содержимого файла'}</small>${x.filePresent?btn('Открыть файл','open-file',{primary:true,id:x.id,icon:'docs'}):btn('Добавить файл','edit-document',{primary:true,id:x.id,icon:'upload'})}</div><div class="detail-heading"><h2>${esc(x.title)}</h2><div class="document-statuses">${badge(x.audience||'Только мне')}${badge(x.filePresent?'Копия на устройстве':'Без локального файла',x.filePresent?'success':'muted')}${t.pins?.includes(x.id)?badge('Закреплён','accent'):''}</div></div><section class="card detail-card">${detailRows([['Категория',x.category||'Другое'],['Владелец записи',x.owner||'На этом устройстве'],['Имя файла',x.fileName||'Файл не выбран'],['Заметки',x.note||x.notes]])}</section><div class="button-row">${btn(t.pins?.includes(x.id)?'Открепить':'Закрепить','toggle-pin',{id:x.id,icon:'pin'})}${btn('Кому доступен','show-integration',{id:x.id,feature:'permissions',icon:'people'})}</div>${event?`<div class="card detail-links">${linkRow(event.title,event.date?dateLabel(event.date):'День не назначен',href(t.id,'event',event.id),'plan')}</div>`:''}${notice('Локальные данные','Файл хранится в этом браузере. Метка аудитории не создаёт серверные права. Общий доступ и синхронизация пока не подключены.')}<div class="secondary-actions">${x.filePresent?btn('Удалить локальную копию','delete-file',{id:x.id,danger:true,ghost:true,icon:'download'}):''}${btn('Удалить запись документа','delete-document',{id:x.id,danger:true,ghost:true,icon:'trash'})}</div><p class="helper-text">Удаление копии сохраняет запись. Удаление записи и её локального файла — отдельное действие с подтверждением.</p></div>`};}

function templates(ctx){const data=ctx.data.templates||[];return {header:header(ctx,'Мои шаблоны',{subtitle:'Личные списки для будущих путешествий',action:'new-template',actionLabel:'Создать шаблон'}),content:`<div class="page-inner templates-page">${data.length?`<div class="template-grid">${data.map(x=>`<article class="template-card card"><span class="round-icon">${icon('packing')}</span><h2><a href="${href(null,'template',x.id)}">${esc(x.name||x.title)}</a></h2><p>${x.items?.length||0} позиций</p><div class="button-row">${btn('Применить','apply-template',{id:x.id,primary:true})}${btn('Копировать','copy-template',{id:x.id,ghost:true})}</div></article>`).join('')}</div>`:emptyState('Ваши сборы — ваш шаблон','Создайте свой список для выходных, похода или ручной клади. Вещи в поездках останутся независимыми.',btn('Создать шаблон','new-template',{primary:true,icon:'plus'}),'packing')}${notice('Каждый раз с чистого листа','Применение добавляет новые вещи в состоянии «Ещё нет». Изменение шаблона не меняет уже добавленные вещи.')}</div>`};}
function templateDetail(ctx){const x=(ctx.data.templates||[]).find(t=>t.id===ctx.route.id);if(!x)return {header:header(ctx,'Шаблон'),content:notFound('Шаблон')};return {header:header(ctx,'Шаблон',{subtitle:'Личный набор вещей',back:'#/templates',action:'edit-template',actionIcon:'edit',actionLabel:'Изменить шаблон',id:x.id}),content:`<div class="page-inner detail-page"><div class="detail-heading"><span class="detail-symbol">${icon('packing')}</span><h2>${esc(x.name||x.title)}</h2><p>${x.items?.length||0} позиций</p></div><div class="card compact-list">${(x.items||[]).map(i=>`<div class="template-item"><strong>${esc(typeof i==='string'?i:i.title)}</strong><span>${typeof i==='string'?'1 шт.':esc(i.quantity||1)+' шт.'}</span>${typeof i!=='string'&&i.category?`<small>${esc(i.category)}</small>`:''}</div>`).join('')||'<p class="empty-inline">В наборе пока нет вещей.</p>'}</div><div class="button-row">${btn('Применить к поездке','apply-template',{primary:true,id:x.id,icon:'plus'})}${btn('Копировать','copy-template',{id:x.id})}</div><div class="secondary-actions">${btn('Редактировать','edit-template',{id:x.id,ghost:true,icon:'edit'})}${btn('Удалить','delete-template',{id:x.id,ghost:true,danger:true,icon:'trash'})}</div></div>`};}

function calendar(ctx){const t=ctx.trip,r=ctx.route;const raw=qget(r,'month',today().slice(0,7));const month=/^\d{4}-\d{2}$/.test(raw)?raw:today().slice(0,7);const first=month+'-01';const d=new Date(first+'T12:00:00Z');const offset=(d.getUTCDay()+6)%7;const days=new Date(d.getUTCFullYear(),d.getUTCMonth()+1,0).getDate();const prev=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()-1,1)).toISOString().slice(0,7);const next=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,1)).toISOString().slice(0,7);const chosen=qget(r,'day');const tasks=t.tasks.filter(x=>x.due?.startsWith(month)&&(!chosen||x.due===chosen));return {header:header(ctx,'Календарь подготовки',{back:href(t.id,'tasks'),action:'new-task',actionLabel:'Добавить задачу'}),content:`<div class="page-inner calendar-page"><div class="calendar-heading"><a class="icon-btn" href="${href(t.id,'calendar',null,{month:prev})}" aria-label="Предыдущий месяц">${icon('arrow')}</a><h2>${esc(dateLabel(first,{month:'long',year:'numeric',day:undefined}))}</h2><a class="icon-btn" href="${href(t.id,'calendar',null,{month:next})}" aria-label="Следующий месяц">${icon('chevron')}</a></div><div class="calendar card"><div class="calendar-weekdays">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-days">${Array(offset).fill('<span class="calendar-blank"></span>').join('')}${Array.from({length:days},(_,i)=>{const day=month+'-'+String(i+1).padStart(2,'0');const count=t.tasks.filter(x=>x.due===day).length;return `<a class="calendar-day ${day===chosen?'selected':''} ${day===today()?'today':''}" href="${href(t.id,'calendar',null,{month,day})}" aria-label="${attr(dateLabel(day,{year:'numeric'}))}${count?`, задач: ${count}`:''}"><span>${i+1}</span>${count?'<i aria-hidden="true"></i>':''}</a>`;}).join('')}</div></div><div class="calendar-tools"><a class="btn ghost" href="${href(t.id,'calendar',null,{month:today().slice(0,7),day:today()})}">Сегодня</a><a class="btn ghost" href="${href(t.id,'tasks',null,{filter:'all'})}">Без срока · ${t.tasks.filter(x=>!x.due).length}</a></div>${sectionTitle(chosen?dateLabel(chosen,{year:'numeric'}):'Задачи месяца')}${tasks.length?`<ul class="task-list">${tasks.sort((a,b)=>a.due.localeCompare(b.due)).map(x=>taskRow(t,x)).join('')}</ul>`:emptyState('На эти даты дел нет','Переходите по месяцам или добавьте задачу с нужным сроком.',btn('Добавить задачу','new-task',{primary:true,icon:'plus'}),'plan')}</div>`};}

function participants(ctx){const t=ctx.trip;return {header:header(ctx,'Участники',{subtitle:ctx.mode==='demo'?'Демонстрационные участники':'Локальные имена в поездке'}),content:`<div class="page-inner participants-page"><div class="card compact-list">${(t.members||['Вы']).map(m=>`<div class="person-row">${avatar(memberName(m))}<span class="row-copy"><strong>${esc(memberName(m))}</strong><small>${ctx.mode==='demo'?'Синтетический участник':'Локальная запись · без аккаунта'}</small></span>${badge(ctx.mode==='demo'?'Демо':'На устройстве')}</div>`).join('')}</div>${notice('Совместная работа не подключена','Локальные имена не являются подтверждёнными аккаунтами. Приглашения, роли и исключение участников требуют сервера.')}<div class="button-row">${btn('Пригласить участника','show-integration',{primary:true,feature:'invitation',icon:'people'})}<a class="btn" href="${href(t.id,'invitation')}">Состояния приглашения</a></div><section class="card detail-card"><h2>Роли и доступ</h2><p>Владелец, редактор и читатель появятся после подключения аккаунтов. Изменение локального имени не выдаёт права на поездку или файлы.</p>${btn('Подробнее о доступе','show-integration',{feature:'permissions',ghost:true})}</section></div>`};}
function invitation(ctx){const state=qget(ctx.route,'state',ctx.route.id||'unavailable');const variants={unavailable:['Приглашения пока недоступны','Сервер совместной работы не подключён. Работающая ссылка не создана.'],expired:['Срок приглашения истёк','Для реального вступления потребуется новое действующее приглашение от владельца.'],revoked:['Приглашение отозвано','Отозванная ссылка не предоставляет доступ к поездке.'],removed:['Доступ отозван','Серверный доступ проверяется перед открытием данных. Локальный интерфейс не восстанавливает отозванные права.']};const [title,text]=variants[state]||variants.unavailable;return {header:header(ctx,'Приглашение',{subtitle:'Интерфейс будущей серверной функции'}),content:`<div class="page-inner">${emptyState(title,text,btn('Почему недоступно','show-integration',{primary:true,feature:'invitation'}),'people')}<p class="helper-text">Ниже — просмотр состояний интерфейса, а не реальные приглашения.</p><div class="chip-strip">${Object.entries({unavailable:'Не подключено',expired:'Истекло',revoked:'Отозвано',removed:'Доступ отозван'}).map(([v,label])=>`<a class="chip ${state===v?'active':''}" href="${href(ctx.trip?.id,'invitation',null,{state:v})}">${label}</a>`).join('')}</div></div>`};}
function contacts(ctx){const t=ctx.trip;return {header:header(ctx,'Контакты и адреса',{action:'new-contact',actionLabel:'Добавить контакт'}),content:`<div class="page-inner">${(t.contacts||[]).length?`<div class="card compact-list">${t.contacts.map(c=>linkRow(c.name||c.title,c.address||c.phone||'Открыть контакт',href(t.id,'contact',c.id),'phone')).join('')}</div>`:emptyState('Важные контакты рядом','Сохраните адрес отеля, телефон хозяина или контакт попутчика.',btn('Добавить контакт','new-contact',{primary:true,icon:'plus'}),'phone')}</div>`};}
function contactDetail(ctx){const t=ctx.trip,c=(t.contacts||[]).find(x=>x.id===ctx.route.id);if(!c)return {header:header(ctx,'Контакт'),content:notFound('Запись')};return {header:header(ctx,'Контакт',{back:href(t.id,'contacts'),action:'edit-contact',actionIcon:'edit',actionLabel:'Редактировать контакт',id:c.id}),content:`<div class="page-inner detail-page"><div class="detail-heading"><span class="detail-symbol">${icon('phone')}</span><h2>${esc(c.name||c.title)}</h2></div><section class="card detail-card">${detailRows([['Телефон',c.phone],['Адрес',c.address],['Заметка',c.notes||c.note]])}</section><div class="button-stack">${c.phone?`<a class="btn primary full" href="tel:${attr(c.phone.replace(/[^+\d]/g,''))}">${icon('phone')}Позвонить</a>`:''}${c.address?`<button type="button" class="btn full" data-action="copy-address" data-address="${attr(c.address)}">${icon('copy')}Скопировать адрес</button><a class="btn full" href="${href(t.id,'map')}">${icon('location')}Открыть карту</a>`:''}${btn('Редактировать','edit-contact',{id:c.id,icon:'edit',full:true})}${btn('Удалить контакт','delete-contact',{id:c.id,danger:true,ghost:true,full:true})}</div></div>`};}
function history(ctx){const t=ctx.trip;const rows=t.history||t.activity||[];return {header:header(ctx,'История поездки'),content:`<div class="page-inner">${notice('Локальный журнал','Здесь отображаются изменения, записанные этим клиентом. Серверный аудит и действия других участников не подключены.')}${rows.length?`<ol class="history-list">${[...rows].reverse().map(x=>`<li><span class="history-dot"></span><div><strong>${esc(x.action||x.text||x.title||'Изменение записи')}</strong><p>${esc(x.author||'На этом устройстве')}${x.time||x.createdAt?` · ${esc(dateLabel(x.time||x.createdAt,{year:'numeric',hour:'2-digit',minute:'2-digit'}))}`:''}</p></div></li>`).join('')}</ol>`:emptyState('История пока пуста','Новые сохранённые изменения будут появляться здесь. Просмотр записей не создаёт изменений.','','clock')}</div>`};}
function mapView(ctx){const t=ctx.trip;const places=[...t.events.filter(e=>e.address).map(e=>({...e,kind:'event'})),...(t.contacts||[]).filter(c=>c.address).map(c=>({...c,title:c.name||c.title,kind:'contact'}))];return {header:header(ctx,'Места на карте',{back:href(t.id,'plan')}),content:`<div class="page-inner"><section class="map-unavailable card"><span class="empty-icon">${icon('location')}</span><h2>Адреса сохранены. Карта впереди.</h2><p>Картографический адаптер не подключён. Маршрут, геолокация и офлайн-карта недоступны.</p>${btn('О подключении карты','show-integration',{feature:'maps',ghost:true})}</section>${sectionTitle('Сохранённые места')}<div class="card compact-list">${places.length?places.map(p=>linkRow(p.title,p.address,href(t.id,p.kind,p.id),'location')).join(''):'<p class="empty-inline">Добавьте адрес в событие или контакт.</p>'}</div></div>`};}

function accounts(ctx){const t=ctx.trip;return {header:header(ctx,'Счета',{back:href(t.id,'budget'),action:'new-account',actionLabel:'Добавить счёт'}),content:`<div class="page-inner"><div class="account-grid">${t.accounts.map(a=>`<button type="button" class="account-card card" data-action="edit-account" data-money-account="${attr(a.id)}" data-id="${attr(a.id)}"><span>${icon(a.kind==='storage'?'building':'wallet')}${esc(a.name)}</span><strong>${money(a.balanceMinor!=null?moneyFromMinor(a.balanceMinor,t.currency):a.balance,t.currency)}</strong><small>Открыть сведения</small></button>`).join('')}</div><div class="button-row">${btn('Новый счёт','new-account',{icon:'plus'})}${btn('Перевести','new-transfer',{primary:true,icon:'transfer'})}</div><div class="card detail-links">${linkRow('История операций',`${t.transactions.length} записей`,href(t.id,'transactions'),'clock')}</div>${notice('Остаток — не бюджет','На счетах показаны доступные деньги после расходов и переводов. История не применяется к этим остаткам повторно.')}</div>`};}
function transactions(ctx){const t=ctx.trip;const account=id=>t.accounts.find(a=>a.id===id)?.name||'Счёт удалён';const category=id=>t.categories.find(a=>a.id===id)?.name||'Без категории';return {header:header(ctx,'История операций',{back:href(t.id,'budget'),action:'new-expense',actionLabel:'Добавить расход'}),content:`<div class="page-inner"><div class="button-row">${btn('Расход','new-expense',{primary:true,icon:'plus'})}${btn('Перевод','new-transfer',{icon:'transfer'})}</div>${t.transactions.length?`<ol class="transaction-list">${[...t.transactions].sort((a,b)=>(typeof b.date==='number'?b.date:Date.parse(b.date||b.createdAt)||0)-(typeof a.date==='number'?a.date:Date.parse(a.date||a.createdAt)||0)).map(x=>`<li class="transaction-row card"><span class="round-icon">${icon(x.type==='transfer'?'transfer':'money')}</span><div class="row-copy"><strong>${esc(x.type==='transfer'?`${account(x.fromId)} → ${account(x.toId)}`:category(x.categoryId))}</strong><small>${esc(x.type==='transfer'?'Перевод между счетами':account(x.fromId))}</small><small>${esc(dateLabel(x.date||x.createdAt,{year:'numeric',hour:'2-digit',minute:'2-digit'}))}${x.note?` · ${esc(x.note)}`:''}</small></div><strong class="transaction-amount ${x.type==='expense'?'spent':''}">${x.type==='expense'?'−':''}${money(x.amountMinor!=null?moneyFromMinor(x.amountMinor,x.currency||t.currency):x.amount,x.currency||t.currency)}</strong><button type="button" class="icon-btn transaction-undo" data-action="delete-transaction" data-id="${attr(x.id)}" aria-label="Отменить операцию: ${attr(x.type==='transfer'?'перевод':category(x.categoryId))}">${icon('refresh')}</button></li>`).join('')}</ol>`:emptyState('Пока без расходов','Добавьте первый расход или переведите деньги между счетами. Перевод не учитывается расходом.',btn('Добавить расход','new-expense',{primary:true}),'money')}</div>`};}
function settlements(ctx){return {header:header(ctx,'Распределение трат',{back:href(ctx.trip.id,'budget')}),content:`<div class="page-inner"><section class="card detail-card"><div class="section-title"><h2>Общие расходы</h2>${badge('Не подключено','accent')}</div><p>Доли участников, взаимные долги и подтверждение погашений требуют общего журнала операций и аккаунтов участников.</p><div class="split-preview"><label><input type="radio" name="split-preview" checked disabled> Поровну</label><label><input type="radio" name="split-preview" disabled> Заданными долями</label></div>${detailRows([['Плательщик','Подтверждённый аккаунт не подключён'],['Участники','Состав из серверной поездки'],['Баланс взаиморасчётов','Пока недоступен']])}</section><div class="card detail-links"><button type="button" class="link-row" data-action="show-integration" data-feature="settlements"><span class="round-icon">${icon('people')}</span><span class="row-copy"><strong>Распределить расход</strong><small>Интерфейс ожидает сервер</small></span>${icon('chevron')}</button><button type="button" class="link-row" data-action="show-integration" data-feature="settlements"><span class="round-icon">${icon('transfer')}</span><span class="row-copy"><strong>Погасить долг</strong><small>Не создаёт повторный общий расход</small></span>${icon('chevron')}</button></div>${notice('Локальные финансы работают','Обычные расходы, остатки на счетах и переводы доступны в бюджете. Чужие долги не вычисляются из локальных имён участников.')}</div>`};}

function profile(ctx){return {header:header(ctx,'Профиль',{subtitle:'Аккаунт и ваше пространство'}),content:`<div class="page-inner profile-page"><section class="profile-card card"><span class="profile-avatar">${icon('user')}</span><h2>${ctx.mode==='demo'?'Демонстрационный профиль':'Аккаунт не подключён'}</h2><p>${ctx.mode==='demo'?'Все участники и сообщения здесь синтетические.':'Сервер авторизации пока не настроен.'}</p>${btn('Вход в аккаунт','show-integration',{primary:true,feature:'auth',icon:'lock'})}</section>${notice(ctx.mode==='demo'?'Отдельный деморежим':'Локальный режим разработки',ctx.mode==='demo'?'Изменения сохраняются только в отдельной демонстрационной базе. Ваши основные поездки не меняются.':'Данные сохраняются в этом браузере. Это режим разработки до подключения обязательной авторизации, а не работающий Google/Apple-вход.')}<div class="card detail-links">${linkRow('Настройки','Тема, уведомления и установка','#/settings','settings')}${linkRow('Данные на устройстве','Локальные файлы, экспорт и хранение','#/storage','download')}${linkRow('Мои шаблоны',`${ctx.data.templates?.length||0} наборов`,'#/templates','packing')}${linkRow('Фотографии и лицензии','Источники обложек и изображений','assets/photos/credits.html','image')}</div><div class="list-footer">${ctx.mode==='demo'?btn('Вернуться к своим данным','leave-demo',{icon:'arrow'}):btn('Открыть деморежим','choose-demo',{icon:'trips'})}</div></div>`};}
function settings(ctx){const selected=ctx.data.settings?.theme|| (ctx.data.dark?'dark':'system');const permission=typeof Notification!=='undefined'?Notification.permission:'unsupported';const installed=typeof matchMedia!=='undefined'&&matchMedia('(display-mode: standalone)').matches;return {header:header(ctx,'Настройки',{back:'#/profile',subtitle:'Всё для удобного путешествия'}),content:`<div class="page-inner settings-page">${notice(ctx.pwa?.offlineReady?'Оболочка готова к офлайн-запуску':'Подготовка офлайн-оболочки',ctx.pwa?.offlineReady?'Код, стили и базовые изображения загружены. Личные файлы доступны только при сохранённой локальной копии.':'После первого успешного открытия приложение загрузит основные ресурсы. Готовность не означает синхронизацию личных файлов.',ctx.pwa?.offlineReady?'success':'info')}<section class="card detail-card"><h2>Оформление</h2><div class="theme-switch" role="group" aria-label="Тема приложения">${[['light','Светлая','sun'],['dark','Тёмная','moon'],['system','Системная','settings']].map(([theme,label,ic])=>`<button type="button" class="theme-option ${selected===theme?'active':''}" data-action="theme" data-theme="${theme}" aria-pressed="${selected===theme}">${icon(ic)}<span>${label}</span></button>`).join('')}</div><label class="field-row"><span>Язык</span><select aria-label="Язык интерфейса" disabled><option>Русский</option></select><small>Другие языки пока не подключены.</small></label></section><section class="card detail-card" id="notification-settings"><h2>Уведомления</h2><p>Разрешение браузера: <strong>${esc({granted:'разрешены',denied:'запрещены',default:'не запрашивалось',unsupported:'не поддерживаются'}[permission])}</strong></p><p>Включение разрешения само по себе не создаёт надёжную доставку при закрытом приложении. Push и серверный планировщик не подключены.</p>${permission==='denied'?notice('Разрешение отклонено','Изменить его можно в настройках сайта вашего браузера. Повторный запрос здесь не откроет окно разрешения.','error'):btn('Запросить разрешение','notifications',{icon:'bell',disabled:permission==='unsupported'||permission==='granted'})}</section><section class="card detail-card"><h2>Установить приложение</h2><p>${installed?'Открыто в отдельном окне установленного приложения.':'Работает и как обычный сайт. Установка зависит от возможностей браузера.'}</p>${btn(installed?'Приложение установлено':'Установить PWA','install',{primary:true,icon:'download',disabled:installed})}<details><summary>Как установить на iPhone</summary><p>В Safari откройте меню «Поделиться», выберите «На экран Домой», проверьте название и нажмите «Добавить». Доступность команды зависит от браузера и режима просмотра.</p></details></section><div class="card detail-links">${linkRow('Локальные данные','Объём, копии и экспорт','#/storage','download')}${linkRow('Состояния приложения','Ошибки, конфликты и обновление','#/states','info')}</div><div class="button-row">${btn('Проверить обновление','check-update',{icon:'refresh'})}</div></div>`};}
function storage(ctx){const allDocs=(ctx.data.trips||[]).flatMap(t=>t.docs||[]);const count=allDocs.filter(d=>d.filePresent).length;const size=allDocs.reduce((s,d)=>s+(d.filePresent?Number(d.fileSize)||0:0),0);const stats=ctx.storageInfo||{};return {header:header(ctx,'Данные на устройстве',{back:'#/settings',subtitle:'Копии, сохранность и перенос'}),content:`<div class="page-inner storage-page"><section class="card detail-card"><div class="storage-icon">${icon('download')}</div><h2>Ваше пространство</h2>${detailRows([['Поездки',String(ctx.data.trips.length)],['Локальные файлы',`${count} · ${formatBytes(size)}`],['Квота origin',stats.quota!=null?formatBytes(stats.quota):'Не сообщена браузером']])}<div class="storage-estimate"><span>Используется браузером</span><strong id="storage-estimate">${stats.usage!=null?formatBytes(stats.usage):'Уточняется браузером'}</strong></div></section><section class="card detail-card"><h2>Резервная копия</h2><p>Экспорт включает предметные записи и сохранённые файлы. Храните копию у себя: очистка браузера может удалить локальные данные.</p><div class="button-stack">${btn('Экспортировать данные','export-data',{primary:true,icon:'download',full:true})}${btn('Импортировать копию','import-data',{icon:'upload',full:true})}</div></section>${notice('О хранении документов','Хранилище браузера не является зашифрованным сейфом. Проекты на одном GitHub Pages origin разделяют его; отдельный путь сайта не обеспечивает изоляцию чувствительных файлов.')}<section class="card detail-card"><h2>Очистка</h2><p>Очищается только пространство TravelOrganizer выбранного режима. Перед очисткой экспортируйте свои записи и файлы.</p>${btn('Очистить данные этого режима','clear-data',{danger:true,ghost:true,icon:'trash'})}</section></div>`};}
function states(ctx){const state=qget(ctx.route,'state','local');const entries={local:['Сохранение на устройстве','Записи остаются в этом браузере. Серверная синхронизация не подключена.','info'],offline:['Сейчас без сети','Локальные записи доступны. Ранее загруженная оболочка приложения работает без сети.','offline'],loading:['Загрузка','Открываем записи и проверяем локальное хранилище.','info'],save:['Не удалось сохранить','Введённые данные остаются в форме. Исправьте причину или экспортируйте записи и повторите сохранение.','error'],pending:['Ожидающие операции','Отправка на сервер не подключена. Локальное сохранение не выдаётся за отправленную операцию.','info'],conflict:['Конфликт изменений','Для серверных правок нужен адаптер синхронизации. Конфликт локальных вкладок не должен молча перезаписывать более новую запись.','error'],revoked:['Доступ отозван','Серверные права пока не подключены. При реализации отзыва недоступные записи нельзя показывать из общего кеша.','error'],update:['Доступна новая версия','Обновление требует успешного сохранения формы или вашего явного решения. Ввод не сбрасывается автоматически.','info']};const selected=entries[state]||entries.local;return {header:header(ctx,'Состояния приложения',{back:'#/settings',subtitle:'Справка о реальном поведении и границах'}),content:`<div class="page-inner"><div class="chip-strip state-chip-strip">${Object.entries({local:'Локально',offline:'Без сети',loading:'Загрузка',save:'Ошибка записи',pending:'Отправка',conflict:'Конфликт',revoked:'Отзыв',update:'Обновление'}).map(([s,label])=>`<a class="chip ${s===state?'active':''}" href="${href(null,'states',null,{state:s})}">${label}</a>`).join('')}</div>${notice(...selected)}${state==='loading'?'<div class="loading-demo" aria-label="Пример индикатора загрузки"><span class="spinner"></span><span>Пример состояния загрузки</span></div>':''}${state==='conflict'?`<section class="card detail-card"><h2>Сравнение полей</h2><p>Пример интерфейса конфликта. Реальные конфликтующие значения появляются при несовпадении ревизий.</p><div class="table-scroll"><table><thead><tr><th>Поле</th><th>Ваша правка</th><th>Более новая запись</th></tr></thead><tbody><tr><td>Название</td><td>Дорожный адаптер</td><td>Адаптер типа A</td></tr><tr><td>Количество</td><td>2</td><td>1</td></tr></tbody></table></div><p class="helper-text">Восстановление новой версии не должно уничтожать несохранённый ввод.</p></section>`:''}${state==='update'?btn('Проверить обновление','check-update',{primary:true,icon:'refresh'}):''}<p class="helper-text">Это справочный экран состояний. Он не создаёт серверные операции, ошибки хранилища или фиктивные обновления.</p></div>`};}

export function renderApp(ctx){ctx={...ctx,route:{page:'trips',query:new URLSearchParams(),...ctx.route}};const page=ctx.route.page;const needTrip=!['trips','archive','profile','settings','storage','templates','template','states','invitation'].includes(page);if(needTrip&&!ctx.trip)return {header:header(ctx,'Поездка не найдена'),content:`<div class="page-inner">${emptyState('Поездка не найдена','Проверьте ссылку или выберите поездку из своего списка.','<a class="btn primary" href="#/trips">Мои поездки</a>','trips')}</div>`,nav:nav(ctx)};const functions={trips:tripsView,archive:tripsView,overview,packing,plan,documents,tasks,discussions,budget,item:itemDetail,event:eventDetail,task:taskDetail,document:documentDetail,templates,template:templateDetail,calendar,participants,invitation,contacts,contact:contactDetail,history,map:mapView,accounts,transactions,settlements,profile,settings,storage,states};const result=(functions[page]||tripsView)(ctx);return {header:result.header??header(ctx,names[page]||'TravelOrganizer'),content:result.content,nav:nav(ctx)};}
